import{_ as t,a as o,o as a,a6 as r}from"./chunks/framework.CJDy2q7X.js";const u=JSON.parse('{"title":"Catalog Rules","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/rest-api/admin/marketing/promotions/catalog-rules/index.md","filePath":"api/rest-api/admin/marketing/promotions/catalog-rules/index.md","lastUpdated":1787725411000}'),d={name:"api/rest-api/admin/marketing/promotions/catalog-rules/index.md"};function n(s,e,i,c,l,p){return a(),o("div",null,e[0]||(e[0]=[r('<h1 id="catalog-rules" tabindex="-1">Catalog Rules <a class="header-anchor" href="#catalog-rules" aria-label="Permalink to &quot;Catalog Rules&quot;">​</a></h1><p>A <strong>catalog rule</strong> automatically lowers a product&#39;s price store-wide — before the product is ever added to a cart. The shopper just sees a reduced price on the product and category pages; there is no coupon and no minimum-cart requirement. It mirrors the admin <strong>Marketing → Promotions → Catalog Rules</strong> screen.</p><h2 id="how-a-catalog-rule-works" tabindex="-1">How a catalog rule works <a class="header-anchor" href="#how-a-catalog-rule-works" aria-label="Permalink to &quot;How a catalog rule works&quot;">​</a></h2><p>A rule has three parts: <strong>who it applies to</strong>, <strong>when it applies</strong>, and <strong>what it does to the price</strong>.</p><ul><li><strong>Who</strong> — <code>channels</code> (which storefront channels) and <code>customer_groups</code> (e.g. general, wholesale). A rule only fires for shoppers in a matching channel + group. In responses these come back as <code>channels</code> / <code>customerGroups</code> — <strong>arrays of objects</strong> (each <code>{ id, code, name }</code>). Requests still send them as plain id arrays.</li><li><strong>When</strong> — an optional date window (<code>starts_from</code> / <code>ends_till</code>) and a set of <code>conditions</code> (product attribute filters such as <em>category = Summer</em> or <em>brand = Acme</em>). <code>condition_type</code> decides whether <strong>all</strong> conditions must match (<code>1</code>) or <strong>any</strong> (<code>0</code>).</li><li><strong>What</strong> — the <code>action_type</code> + <code>discount_amount</code> rewrite the price:</li></ul><table tabindex="0"><thead><tr><th><code>action_type</code></th><th>Effect</th><th>Example with <code>discount_amount: 10</code></th></tr></thead><tbody><tr><td><code>by_percent</code></td><td>Reduce by N%</td><td>$100 → $90</td></tr><tr><td><code>by_fixed</code></td><td>Reduce by a fixed amount</td><td>$100 → $90</td></tr><tr><td><code>to_percent</code></td><td>Set price to N% of original</td><td>$100 → $10</td></tr><tr><td><code>to_fixed</code></td><td>Set price to a fixed amount</td><td>$100 → $10</td></tr></tbody></table><p>For <code>by_percent</code>, <code>discount_amount</code> is capped at <code>100</code>.</p><p><strong>Priority and stacking.</strong> <code>sort_order</code> sets evaluation priority (lower runs first). <code>end_other_rules</code> (<code>1</code>) stops any lower-priority rule from also applying once this one matches.</p><p><strong>Status and re-indexing.</strong> <code>status</code> (<code>0</code>/<code>1</code>) toggles the rule on. Saving a rule recomputes affected product prices in the background, so a newly-created or edited rule can take a moment to show on the storefront.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Endpoint</th></tr></thead><tbody><tr><td><a href="/api/rest-api/admin/marketing/promotions/catalog-rules-list.html">List</a></td><td><code>GET /api/admin/marketing/catalog-rules</code></td></tr><tr><td><a href="/api/rest-api/admin/marketing/promotions/catalog-rules-detail.html">Detail</a></td><td><code>GET /api/admin/marketing/catalog-rules/{id}</code></td></tr><tr><td><a href="/api/rest-api/admin/marketing/promotions/catalog-rules-create.html">Create</a></td><td><code>POST /api/admin/marketing/catalog-rules</code></td></tr><tr><td><a href="/api/rest-api/admin/marketing/promotions/catalog-rules-update.html">Update</a></td><td><code>PUT /api/admin/marketing/catalog-rules/{id}</code></td></tr><tr><td><a href="/api/rest-api/admin/marketing/promotions/catalog-rules-delete.html">Delete</a></td><td><code>DELETE /api/admin/marketing/catalog-rules/{id}</code></td></tr><tr><td><a href="/api/rest-api/admin/marketing/promotions/catalog-rules-mass-delete.html">Mass Delete</a></td><td><code>POST /api/admin/marketing/catalog-rules/mass-delete</code></td></tr></tbody></table><p><code>conditions</code>, <code>channels</code>, and <code>customerGroups</code> are returned only on the <strong>detail</strong>, <strong>create</strong>, and <strong>update</strong> responses — they are <code>null</code> on list rows. <code>channels</code> and <code>customerGroups</code> are arrays of <code>{ id, code, name }</code> objects.</p>',12)]))}const h=t(d,[["render",n]]);export{u as __pageData,h as default};
